  "lo": "ຈຳນວນຈ່າຍ {tra} ເກີນຍອດຄ້າງ {no} ກີບ (ຫັກສ່ວນລໍຖ້າຈ່າຍແລ້ວ). ຍັງສ້າງໃບສະເໜີບໍ?",
